// Package app owns the top-level dependency wiring for the IAM process.
package app

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"time"

	"benchmark.local/iam/internal/config"
	"benchmark.local/iam/internal/domain"
	"benchmark.local/iam/internal/repository"
	"benchmark.local/iam/internal/security"
)

const MaxRequestBodyBytes int64 = 1 << 20

type App struct {
	Config config.Config
	Clock  domain.Clock
	Users  *repository.UserRepository
	Tokens *security.AccessTokenIssuer
}

type DataEnvelope struct {
	Data any `json:"data"`
}

type ErrorDetails struct {
	Code      string `json:"code"`
	Message   string `json:"message"`
	RequestID string `json:"request_id"`
}

type ErrorEnvelope struct {
	Error ErrorDetails `json:"error"`
}

func New(cfg config.Config) (*App, error) {
	return NewWithClock(cfg, domain.SystemClock{})
}

func NewWithClock(cfg config.Config, clock domain.Clock) (*App, error) {
	if err := cfg.Validate(); err != nil {
		return nil, err
	}
	if clock == nil {
		return nil, domain.Invalid("clock must not be nil")
	}
	tokens, err := security.NewAccessTokenIssuer([]byte(cfg.HMACSecret), cfg.Issuer, cfg.AccessTokenTTL, clock)
	if err != nil {
		return nil, domain.Invalid("access token configuration is invalid")
	}
	return &App{Config: cfg, Clock: clock, Users: repository.NewUserRepository(), Tokens: tokens}, nil
}

func (a *App) Handler() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("POST /v1/register", a.register)
	mux.HandleFunc("POST /v1/login", a.login)
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		writeData(w, http.StatusOK, map[string]string{"status": "ok"})
	})
	mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, _ *http.Request) {
		writeData(w, http.StatusOK, map[string]string{"status": "ready"})
	})
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		requestID := r.Header.Get("X-Request-ID")
		if requestID == "" {
			if id, err := domain.NewID(); err == nil {
				requestID = string(id)
			} else {
				requestID = "unknown"
			}
		}
		w.Header().Set("X-Request-ID", requestID)
		r.Body = http.MaxBytesReader(w, r.Body, MaxRequestBodyBytes)
		mux.ServeHTTP(w, r)
	})
}

type registerRequest struct {
	Email    string `json:"email"`
	Password string `json:"password"`
}

type loginRequest struct {
	Email    string `json:"email"`
	Password string `json:"password"`
}

func (a *App) register(w http.ResponseWriter, r *http.Request) {
	var request registerRequest
	if err := decodeJSON(r, &request); err != nil {
		if _, tooLarge := err.(*http.MaxBytesError); tooLarge {
			writeError(w, r, http.StatusRequestEntityTooLarge, "body_too_large", "request body is too large")
			return
		}
		writeError(w, r, http.StatusBadRequest, "invalid_request", "request body is invalid")
		return
	}
	email, err := domain.NormalizeEmail(request.Email)
	if err != nil {
		writeError(w, r, http.StatusBadRequest, "invalid_email", "email is invalid")
		return
	}
	material, err := security.HashPassword(request.Password)
	if err != nil {
		writeError(w, r, http.StatusBadRequest, "invalid_password", "password does not meet policy")
		return
	}
	id, err := domain.NewUserID()
	if err != nil {
		writeError(w, r, http.StatusInternalServerError, "internal_error", "unable to create user")
		return
	}
	now := a.Clock.Now()
	user := domain.User{
		ID:                id,
		Email:             domain.Email(email),
		EmailVerification: domain.EmailUnverified,
		PasswordMaterial:  material,
		CreatedAt:         now,
		UpdatedAt:         now,
	}
	if err := a.Users.Create(user); err != nil {
		if errors.Is(err, domain.ErrConflict) {
			writeError(w, r, http.StatusConflict, "conflict", "email is already registered")
			return
		}
		writeError(w, r, http.StatusBadRequest, "invalid_request", "user could not be created")
		return
	}
	writeData(w, http.StatusCreated, user.PublicProfile())
}

func (a *App) login(w http.ResponseWriter, r *http.Request) {
	var request loginRequest
	if err := decodeJSON(r, &request); err != nil {
		if _, tooLarge := err.(*http.MaxBytesError); tooLarge {
			writeError(w, r, http.StatusRequestEntityTooLarge, "body_too_large", "request body is too large")
			return
		}
		writeUnauthorized(w, r)
		return
	}
	email, err := domain.NormalizeEmail(request.Email)
	if err != nil {
		writeUnauthorized(w, r)
		return
	}
	user, err := a.Users.FindByEmail(domain.Email(email))
	if err != nil || !security.VerifyPassword(user.PasswordMaterial, request.Password) {
		writeUnauthorized(w, r)
		return
	}
	token, err := a.Tokens.Issue(user.ID, user.Email)
	if err != nil {
		writeError(w, r, http.StatusInternalServerError, "internal_error", "unable to create access token")
		return
	}
	writeData(w, http.StatusOK, map[string]any{
		"access_token": token,
		"token_type":   "Bearer",
		"expires_in":   int64(a.Config.AccessTokenTTL / time.Second),
	})
}

func writeUnauthorized(w http.ResponseWriter, r *http.Request) {
	writeError(w, r, http.StatusUnauthorized, "unauthorized", "invalid credentials")
}

func decodeJSON(r *http.Request, dst any) error {
	decoder := json.NewDecoder(r.Body)
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(dst); err != nil {
		return err
	}
	var extra any
	if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
		if err == nil {
			return errors.New("multiple JSON values")
		}
		return err
	}
	return nil
}

func writeData(w http.ResponseWriter, status int, data any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(DataEnvelope{Data: data})
}

func writeError(w http.ResponseWriter, r *http.Request, status int, code, message string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(ErrorEnvelope{Error: ErrorDetails{
		Code: code, Message: message, RequestID: r.Header.Get("X-Request-ID"),
	}})
}
package security

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"strings"
	"time"

	"benchmark.local/iam/internal/domain"
)

type AccessTokenIssuer struct {
	secret []byte
	issuer string
	ttl    time.Duration
	clock  domain.Clock
}

type AccessTokenClaims struct {
	Subject string `json:"sub"`
	Email   string `json:"email"`
	Issuer  string `json:"iss"`
	Issued  int64  `json:"iat"`
	Expires int64  `json:"exp"`
	JTI     string `json:"jti"`
}

func NewAccessTokenIssuer(secret []byte, issuer string, ttl time.Duration, clock domain.Clock) (*AccessTokenIssuer, error) {
	if len(secret) < 32 {
		return nil, errors.New("access token secret must be at least 32 bytes")
	}
	if issuer == "" || ttl <= 0 || clock == nil {
		return nil, errors.New("access token issuer configuration is invalid")
	}
	return &AccessTokenIssuer{
		secret: append([]byte(nil), secret...),
		issuer: issuer,
		ttl:    ttl,
		clock:  clock,
	}, nil
}

func (i *AccessTokenIssuer) Issue(userID domain.UserID, email domain.Email) (string, error) {
	if i == nil || i.clock == nil {
		return "", errors.New("access token issuer is not configured")
	}
	var rawJTI [16]byte
	if _, err := rand.Read(rawJTI[:]); err != nil {
		return "", errors.New("access token id generation failed")
	}
	now := i.clock.Now().UTC()
	claims := AccessTokenClaims{
		Subject: string(userID),
		Email:   string(email),
		Issuer:  i.issuer,
		Issued:  now.Unix(),
		Expires: now.Add(i.ttl).Unix(),
		JTI:     hex.EncodeToString(rawJTI[:]),
	}
	header, err := json.Marshal(struct {
		Algorithm string `json:"alg"`
		Type      string `json:"typ"`
	}{Algorithm: "HS256", Type: "JWT"})
	if err != nil {
		return "", fmt.Errorf("encode access token header: %w", err)
	}
	payload, err := json.Marshal(claims)
	if err != nil {
		return "", fmt.Errorf("encode access token claims: %w", err)
	}
	codec := base64.RawURLEncoding
	signingInput := codec.EncodeToString(header) + "." + codec.EncodeToString(payload)
	mac := hmac.New(sha256.New, i.secret)
	_, _ = mac.Write([]byte(signingInput))
	return signingInput + "." + codec.EncodeToString(mac.Sum(nil)), nil
}

// Validate verifies an access token's structure, algorithm, signature and
// registered claims. The returned claims are safe to use only after all these
// checks have succeeded.
func (i *AccessTokenIssuer) Validate(token string) (AccessTokenClaims, error) {
	var zero AccessTokenClaims
	if i == nil || len(i.secret) == 0 || i.clock == nil {
		return zero, errors.New("access token validator is not configured")
	}
	parts := strings.Split(token, ".")
	if len(parts) != 3 || parts[0] == "" || parts[1] == "" || parts[2] == "" {
		return zero, errors.New("access token format is invalid")
	}
	codec := base64.RawURLEncoding
	headerBytes, err := codec.DecodeString(parts[0])
	if err != nil {
		return zero, errors.New("access token header is invalid")
	}
	payloadBytes, err := codec.DecodeString(parts[1])
	if err != nil {
		return zero, errors.New("access token claims are invalid")
	}
	providedSignature, err := codec.DecodeString(parts[2])
	if err != nil {
		return zero, errors.New("access token signature is invalid")
	}

	var header struct {
		Algorithm string `json:"alg"`
		Type      string `json:"typ"`
	}
	if err := decodeStrictJSON(headerBytes, &header); err != nil || header.Algorithm != "HS256" || header.Type != "JWT" {
		return zero, errors.New("access token header is invalid")
	}

	var claims AccessTokenClaims
	if err := decodeStrictJSON(payloadBytes, &claims); err != nil {
		return zero, errors.New("access token claims are invalid")
	}
	if claims.Subject == "" || claims.Email == "" || claims.Issuer == "" || claims.JTI == "" || claims.Issued <= 0 || claims.Expires <= 0 {
		return zero, errors.New("access token claims are incomplete")
	}
	if claims.Issuer != i.issuer {
		return zero, errors.New("access token issuer is invalid")
	}
	if claims.Expires <= claims.Issued || i.clock.Now().Unix() >= claims.Expires {
		return zero, errors.New("access token is expired")
	}

	mac := hmac.New(sha256.New, i.secret)
	_, _ = mac.Write([]byte(parts[0] + "." + parts[1]))
	expectedSignature := mac.Sum(nil)
	if subtle.ConstantTimeCompare(expectedSignature, providedSignature) != 1 {
		return zero, errors.New("access token signature is invalid")
	}
	return claims, nil
}

func decodeStrictJSON(data []byte, destination any) error {
	decoder := json.NewDecoder(strings.NewReader(string(data)))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(destination); err != nil {
		return err
	}
	var extra any
	if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
		return errors.New("multiple JSON values")
	}
	return nil
}
